57	function createWorksEngine(
58	  canvasId: string,
59	  canvasElement?: HTMLCanvasElement | null,
60	): Engine {
61	  const three = WorksSceneDefinition.createThreeConfig(canvasId);
62	  return new Engine({
63	    canvasId: three.canvasId,
64	    canvasElement,
65	    camera: three.camera,
66	    cameraTarget: three.cameraTarget,
67	    renderer: three.renderer,
68	    pixelRatioMax: three.pixelRatioMax,
69	    shadowMap: three.shadowMap,
70	    renderBudget: three.renderBudget,
71	    scene: three.scene,
72	    postProcessing: three.postProcessing,
73	  });
74	}
