76	function createWorksAuthorState(engine: Engine): WorksAuthorState {
77	  const camera = engine.getCamera();
78	  const target = engine.getCameraTarget();
79	  const sceneLightObject = engine.getSceneObjectById(sceneLights) as
80	    | SceneLightsPort
81	    | null;
82	  const windowObject = engine.getObjectById(windowObj) as
83	    | {
84	        position?: { x: number; y: number; z: number };
85	        scale?: { x: number; y: number; z: number };
86	        visible?: boolean;
87	      }
88	    | null;
89	  const windowRotation = Helpers.readRotationDeg(windowObject as never);
90	  return {
91	    camera: {
92	      position: {
93	        x: camera.position.x,
94	        y: camera.position.y,
95	        z: camera.position.z,
96	      },
97	      target: {
98	        x: target.position.x,
99	        y: target.position.y,
100	        z: target.position.z,
101	      },
102	      fov: camera.fov,
103	    },
104	    sceneLights: normalizeWorksSceneLightsState(sceneLightObject?.getState()),
105	    window: {
106	      position: {
107	        x: windowObject?.position?.x ?? 0,
108	        y: windowObject?.position?.y ?? 0,
109	        z: windowObject?.position?.z ?? 0,
110	      },
111	      rotation: {
112	        x: windowRotation.x,
113	        y: windowRotation.y,
114	        z: windowRotation.z,
115	      },
116	      scale: {
117	        x: windowObject?.scale?.x ?? 1,
118	        y: windowObject?.scale?.y ?? 1,
119	        z: windowObject?.scale?.z ?? 1,
120	      },
121	      visible: windowObject?.visible ?? true,
122	    },
123	  };
124	}
125	
126	function createWorksAuthorSceneState(state: WorksAuthorState): SceneFromState {
127	  const windowPosition = state.window?.position ?? { x: 0, y: 0, z: 0 };
128	  const windowRotation = state.window?.rotation ?? { x: 0, y: 0, z: 0 };
129	  const windowScale = state.window?.scale ?? { x: 1, y: 1, z: 1 };
130	  return {
131	    camera: {
132	      position: { ...state.camera.position },
133	      fov: state.camera.fov,
134	    },
135	    cameraTarget: {
136	      position: { ...state.camera.target },
137	    },
138	    [sceneLights]: {
139	      ...state.sceneLights,
140	      ground: {
141	        position: { ...state.sceneLights.ground.position },
142	        rotation: { ...state.sceneLights.ground.rotation },
143	        scale: { ...state.sceneLights.ground.scale },
144	        visible: state.sceneLights.ground.visible,
145	      },
146	    } as Record<string, unknown>,
147	    [windowObj]: {
148	      position: { ...windowPosition },
149	      rotation: { ...windowRotation },
150	      scale: { ...windowScale },
151	      visible: state.window?.visible ?? true,
152	    } as Record<string, unknown>,
153	  };
154	}
