156	function createDefaultWorksAuthorState(): WorksAuthorState {
157	  return {
158	    camera: {
159	      position: { x: 0, y: 0, z: 0 },
160	      target: { x: 0, y: 0, z: 0 },
161	      fov: 64,
162	    },
163	    sceneLights: {
164	      ...MAIN_SCENE_LIGHT_STATE_DEFAULTS,
165	      ground: {
166	        position: { ...MAIN_SCENE_LIGHT_STATE_DEFAULTS.ground.position },
167	        rotation: { ...MAIN_SCENE_LIGHT_STATE_DEFAULTS.ground.rotation },
168	        scale: { ...MAIN_SCENE_LIGHT_STATE_DEFAULTS.ground.scale },
169	        visible: MAIN_SCENE_LIGHT_STATE_DEFAULTS.ground.visible,
170	      },
171	    },
172	    window: {
173	      position: { x: 0, y: 0, z: 0 },
174	      rotation: { x: 0, y: 0, z: 0 },
175	      scale: { x: 1, y: 1, z: 1 },
176	      visible: true,
177	    },
178	  };
