181	export class WorksTheatreBridge {
182	  private static readonly _statusId = "works-theatre-status";
183	  private static readonly _exportButtonId = "works-theatre-export";
184	  private static readonly _sheetSelectId = "works-theatre-sheet-select";
185	
186	  private _engine: Engine | null = null;
187	  private _objectSetup: ObjectSetup | null = null;
188	  private _controls: OrbitControls | null = null;
189	  private _authorSheetId: WorksTheatreSheetId = WORKS_THEATRE_SHEET_IDS[0] ?? "works";
190	  private readonly _sheetById = new Map<
191	    WorksTheatreSheetId,
192	    TheatreSheetPort<WorksAuthorState, WorksAuthorState>
193	  >();
194	  private readonly _objectBySheetId = new Map<
195	    WorksTheatreSheetId,
196	    TheatreObjectPort<WorksAuthorState, WorksAuthorState>
197	  >();
198	  private _unsubscribeValues: (() => void) | null = null;
199	  private _recordScrub: TheatreScrubPort<WorksAuthorState, WorksAuthorState> | null =
200	    null;
201	  private _sampling = false;
202	  private _lastSampleAt = 0;
203	  private readonly _onControlsStart = () => this._recordStart();
204	  private readonly _onControlsEnd = () => this._recordEnd();
205	  private readonly _onControlsChange = () => this._recordFrame();
206	  private readonly _onExportClick = () => void this._exportSaveFile();
207	  private readonly _onSheetChange = (event: Event) => {
208	    const select = event.currentTarget;
209	    if (!(select instanceof HTMLSelectElement)) return;
210	    this._setAuthorSheetId(select.value);
211	  };
212	
213	  async run(
214	    canvasId: string,
215	    canvasElement?: HTMLCanvasElement | null,
216	  ): Promise<void> {
217	    const engine = createWorksEngine(canvasId, canvasElement);
218	    if (!engine.init()) return;
219	    this._engine = engine;
220	    this._objectSetup = new ObjectSetup();
221	    const config = WorksSceneDefinition.createIntroPageConfig(
222	      canvasId,
223	      WorksSceneDefinition.createInitialState(
224	        createWorksAuthorSceneState(createDefaultWorksAuthorState()),
225	      ),
226	    );
227	    await this._objectSetup.init(engine, config);
228	    engine.setState(config.initialState ?? {});
229	    engine.start(() => undefined, () => undefined);
230	
231	    const renderer = engine.getRenderer() as { domElement?: HTMLCanvasElement } | null;
232	    const domElement = renderer?.domElement;
233	    if (!domElement) return;
234	    this._controls = new OrbitControls(engine.getCamera(), domElement);
235	    this._controls.target = engine.getCameraTarget().position;
236	    this._controls.enableDamping = true;
237	    this._controls.update();
238	
239	    await TheatreStudioService.ensureReady("works");
240	    TheatreStudioService.restoreUi();
241	
242	    const project = TheatreProjectSession.open<WorksAuthorState, WorksAuthorState>(
243	      WORKS_THEATRE_PROJECT_ID,
244	      {
245	        state: readWorksTheatreAuthorStateSource() ?? undefined,
246	      },
247	    );
248	    await project.ready;
249	    WORKS_THEATRE_SHEET_IDS.forEach((sheetId) => {
250	      const sheet = TheatreSheetSession.open(project, sheetId);
251	      const object = sheet.object(
252	        WORKS_THEATRE_OBJECT_ID,
253	        createWorksAuthorState(engine),
254	        { reconfigure: true },
255	      );
256	      this._sheetById.set(sheetId, sheet);
257	      this._objectBySheetId.set(sheetId, object);
258	    });
259	    this._attachSheet(this._authorSheetId);
260	    this._bindControls();
261	    this._renderSheetSelector();
262	    this._renderExportButton();
263	    this._renderStatus("WORKS THEATRE READY");
264	  }
265	
266	  dispose(): void {
267	    this._controls?.removeEventListener("start", this._onControlsStart);
268	    this._controls?.removeEventListener("end", this._onControlsEnd);
269	    this._controls?.removeEventListener("change", this._onControlsChange);
270	    this._controls?.dispose();
271	    this._controls = null;
272	    this._recordScrub?.discard();
273	    this._recordScrub = null;
274	    this._unsubscribeValues?.();
275	    this._unsubscribeValues = null;
276	    TheatreStudioService.removeAuthorControl(
277	      WorksTheatreBridge._exportButtonId,
278	      "button",
279	      this._onExportClick as EventListener,
280	    );
281	    TheatreStudioService.removeAuthorControl(
282	      WorksTheatreBridge._sheetSelectId,
283	      "select",
284	      this._onSheetChange as EventListener,
285	    );
286	    TheatreStudioService.removeAuthorControl(WorksTheatreBridge._statusId, "status");
287	    this._sheetById.clear();
288	    this._objectBySheetId.clear();
289	    this._objectSetup?.dispose();
290	    this._objectSetup = null;
291	    this._engine?.dispose();
292	    this._engine = null;
293	  }
294	
295	  private _attachSheet(sheetId: WorksTheatreSheetId): void {
296	    const sheet = this._sheetById.get(sheetId);
297	    const object = this._objectBySheetId.get(sheetId);
298	    if (!sheet || !object || !this._engine) return;
299	    this._unsubscribeValues?.();
300	    this._authorSheetId = sheetId;
301	    this._unsubscribeValues = TheatrePlaybackService.bindValues(
302	      object,
303	      (values: WorksAuthorState) => {
304	        if (!this._engine) return;
305	        this._engine.setState(
306	          WorksSceneDefinition.createInitialState(
307	            createWorksAuthorSceneState(values),
308	          ),
309	        );
310	        this._applySceneLightsState(values);
311	        this._syncControlsToCameraState();
312	      },
313	    );
314	    TheatreStudioService.setSelection([sheet, object]);
315	    this._renderStatus(`ACTIVE SHEET ${sheetId.toUpperCase()}`);
316	  }
317	
318	  private _applySceneLightsState(values: WorksAuthorState): void {
319	    if (!this._engine) return;
320	    const sceneLightObject = this._engine.getSceneObjectById(sceneLights) as
321	      | SceneLightsPort
322	      | null;
323	    if (!sceneLightObject) return;
324	    sceneLightObject.setState(
325	      normalizeWorksSceneLightsState(values.sceneLights),
326	    );
327	  }
328	
329	  private _bindControls(): void {
330	    if (!this._controls) return;
331	    this._controls.addEventListener("start", this._onControlsStart);
332	    this._controls.addEventListener("end", this._onControlsEnd);
333	    this._controls.addEventListener("change", this._onControlsChange);
334	  }
335	
336	  private _recordStart(): void {
337	    this._sampling = true;
338	    this._recordScrub?.discard();
339	    this._recordScrub = TheatreStudioService.createScrub<
340	      WorksAuthorState,
341	      WorksAuthorState
342	    >();
343	    this._recordFrame(true);
344	  }
