338	  updateDrag(
339	    viewport: WorksViewportSnapshot,
340	    halfView: WorksHalfViewBounds,
341	    pointer: WorksPointerSample,
342	    velMultiplier = 1,
343	  ): void {
344	    if (!this._isDragging) return;
345	    const dx = pointer.x - this._dragPrevious.x;
346	    const dy = pointer.y - this._dragPrevious.y;
347	    this._targetX += (-dx * (halfView.hW * 2)) / viewport.width;
348	    this._targetY += (dy * (halfView.hH * 2)) / viewport.height;
349	    this._velocityX = ((-dx * (halfView.hW * 2)) / viewport.width) * 0.7 * velMultiplier;
350	    this._velocityY = ((dy * (halfView.hH * 2)) / viewport.height) * 0.7 * velMultiplier;
351	    this._targetX = Math.max(
352	      this._dynClampMinX + halfView.hW,
353	      Math.min(this._dynClampMaxX - halfView.hW, this._targetX),
354	    );
355	    this._targetY = Math.max(
356	      this._dynClampMinY + halfView.hH,
357	      Math.min(this._dynClampMaxY - halfView.hH, this._targetY),
358	    );
359	    this._dragPrevious = { ...pointer };
360	  }
