670	  update(delta: number): void {
671	    if (!this.camera || !this.scene) return;
672	    const camera = this.camera;
673	    this.cameraMotionRuntime.updateFrame(camera, delta);
674	
675	    // Hover video: activate / deactivate when hovered mesh changes
676	    if (this.hovered !== this._prevHovered) {
677	      if (this._prevHovered) this._hoverVideo.deactivate();
678	      if (this.hovered) {
679	        const userData = this.hovered.userData as WorkCardUserData;
680	        if (userData.proj.thumbnailVideo) {
681	          const material = this.hovered.material as THREE.MeshBasicMaterial;
682	          const texture = material.map;
683	          if (texture instanceof THREE.CanvasTexture) {
684	            this._hoverVideo.activate(
685	              this.hovered,
686	              texture,
687	              userData.proj.thumbnailVideo,
688	              userData.proj,
689	              this._cardSize,
690	              userData.loadedImage ?? null,
691	            );
692	          }
693	        }
694	      }
695	      this._prevHovered = this.hovered;
696	    }
697	    if (this._hoverVideo.isActive()) this._hoverVideo.drawFrame();
698	
699	    const positionFactor = 1 - Math.pow(1 - this.layout.positionLerp, delta * 60);
700	    const opacityFactor = 1 - Math.pow(1 - this.layout.opacityLerp, delta * 60);
701	    const scaleFactor = 1 - Math.pow(1 - this.layout.scaleLerp, delta * 60);
702	    const isGridView = this.viewMode === "grid";
703	    const hover =
704	      this.hovered && this.isMeshInCategory(this.hovered) ? this.hovered : null;
705	    const blendT =
706	      this._filterBlendStartMs > 0
707	        ? Math.min(
708	            1,
709	            (performance.now() - this._filterBlendStartMs) /
710	              WorksSceneManager._filterBlendMs,
711	          )
712	        : 1;
713	    const filterEase = 1 - Math.pow(1 - blendT, 3);
714	    for (let index = 0; index < this.meshes.length; index += 1) {
715	      const mesh = this.meshes[index];
716	      const target = this.targetPositions[index] ?? this.scatterPositions[index];
717	      const isActiveCategory = this.isMeshInCategory(mesh);
718	      const wasIn = this._meshIncludedInFilter(mesh, this._filterPrevCategory);
719	      const nowIn = isActiveCategory;
720	      let targetY = target.y;
721	      if (wasIn && !nowIn && blendT < 1) {
722	        targetY += (1 - filterEase) * 6.5;
723	      }
724	      if (!wasIn && nowIn && blendT < 1) {
725	        targetY -= (1 - filterEase) * 7.5;
726	      }
727	      mesh.position.x += (target.x - mesh.position.x) * positionFactor;
728	      mesh.position.y += (targetY - mesh.position.y) * positionFactor;
729	      mesh.position.z += (0 - mesh.position.z) * positionFactor;
730	      mesh.quaternion.copy(camera.quaternion);
731	      const opacityAnchor = isActiveCategory ? target : mesh.position;
732	      const distance = dist2d(
733	        camera.position.x,
734	        camera.position.y,
735	        opacityAnchor.x,
736	        opacityAnchor.y,
737	      );
738	      let targetOpacity = Math.max(0, Math.min(0.92, 1 - (distance - 8) * 0.025));
739	      if (!isActiveCategory) targetOpacity = 0;
740	      if (isActiveCategory && this.activeCategory !== null) {
741	        targetOpacity = Math.max(0.3, targetOpacity);
742	      }
743	      if (isGridView) targetOpacity = 0;
744	      if (hover) targetOpacity = hover === mesh ? 1 : targetOpacity * 0.55;
745	      if (nowIn && !wasIn) {
746	        targetOpacity *= filterEase;
747	      }
748	      const material = mesh.material as THREE.MeshBasicMaterial;
749	      material.opacity += (targetOpacity - material.opacity) * opacityFactor;
750	      const steadyScale = (hover === mesh ? 1.06 : 1) * this._cardScale;
751	      mesh.scale.x += (steadyScale - mesh.scale.x) * scaleFactor;
752	      mesh.scale.y += (steadyScale - mesh.scale.y) * scaleFactor;
753	    }
754	  }
